<div class="mb-5 flex justify-end"><a class="rounded-2xl bg-cyan-300 px-5 py-3 font-black text-slate-950" href="<?= e(app_url('product-create', [], 'admin')) ?>">Add Product</a></div><div class="overflow-x-auto rounded-3xl border border-white/10 bg-white/5"><table class="admin-table"><tr><th>Product</th><th>Vendor</th><th>Type</th><th>Approval</th><th>Price</th><th>Actions</th></tr><?php foreach ($products as $product): ?><tr><td><b><?= e($product['name']) ?></b><p class="text-xs text-slate-400"><?= e($product['category_name']) ?></p></td><td><?= e($product['store_name']) ?></td><td><?= e($product['product_type']) ?></td><td><?= e($product['approval_status']) ?></td><td><?= money($product['sale_price'] ?: $product['regular_price']) ?></td><td><a class="text-cyan-300" href="<?= e(app_url('product-edit', ['id' => $product['id']], 'admin')) ?>">Edit</a><form class="mt-2 inline" method="post" action="<?= e(app_url('approve-product', [], 'admin')) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int) $product['id'] ?>"><input type="hidden" name="approval_status" value="approved"><input type="hidden" name="status" value="published"><button class="ml-3 text-emerald-300">Approve</button></form></td></tr><?php endforeach; ?></table></div>
